// Copies the shared test vectors from the vault into the physics package. The JSON is generated by the vault's
// reference_vectors.py; never hand-edit it here or there. Usage: npm run sync-vectors -- <path to test-vectors.json>
import { copyFileSync } from 'node:fs';

const src = process.argv[2];
if (!src) throw new Error('usage: npm run sync-vectors -- <path to test-vectors.json>');
copyFileSync(src, new URL('../packages/physics/test/test-vectors.json', import.meta.url));
console.log(`copied ${src}`);
